    // N119: stay ambiguously rejected until self-fix-generic lands.
    // xUnit checks managed vib-self; the R2 replay kit checks native vib-stage2 too.
    [Theory]
    [MemberData(nameof(N119GenericBodyGuards))]
    public void CollectionElement_GenericBodyMoreSpecificity_StaysAmbiguouslyRejected(string name, string source, string expectedIds)
    {
        _ = name;
        string directory = Path.Combine(Path.GetTempPath(), $"vibranium-r12-n119-guard-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        try
        {
            string path = Path.Combine(directory, "Program.cs");
            File.WriteAllText(path, source);
            var (exit, output, error) = Round12RuleWitness.Run(Round11AuditAssertions.DotnetExe, null,
                Round11AuditAssertions.SelfCompiler, "check", path, "--sysroot", Path.Combine(Round11AuditAssertions.RepoRoot, "src"));
            Assert.True(exit == 1, $"Expected vib-self to reject with exit 1, got {exit}:\n{output}{error}");
            string gotIds = string.Join(",", Regex.Matches(output + error, @"error (VIB\d{3}):")
                .Select(m => m.Groups[1].Value).Distinct().Order(StringComparer.Ordinal));
            Assert.Equal(expectedIds, gotIds);
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

