    private static string BuildNestedCollectionShape(string family, int depth)
    {
        string e = "1";
        for (int i = 0; i < depth; i++)
        {
            e = family switch
            {
                "coll2" or "coll-nest" or "cA" => $"H.F([{e}])",
                "f-cA" => $"H.F([(int)(kk = {e})])",
                "f-cAnd" => $"H.F([(T.G(out int y{i}) == 0 && {e} > 0 ? 1 : 0)])",
                "f-cE" => $"H.F([new BoxS().EchoX({e})])",
                "f-cN2" => $"H.F([new W2({e}).V])",
                "f-cNeg" => $"H.F([-({e})])",
                "f-cR" => $"H.F([T.MkB(out int y{i}).Sel({e})])",
                "f-cS" => $"H.F([1 << ({e})])",
                "f-cSc" => $"H.F([(int)(1L << H.F([{e}]))])",
                "f-cSome" => $"H.F([Pass(Some<int>({e}))])",
                "f-cU" => $"H.F([ol.UnwrapOr({e})])",
                _ => $"H.F([ux[^({e} + 1)]])",
            };
        }
        var sb = new StringBuilder();
        if (family == "f-cA") sb.Append("long kk = 0; ");
        if (family == "f-cU") sb.Append("Option<int> ol = Some(1); ");
        if (family == "f-cX") sb.Append("var ux = new UX(); ");
        sb.Append($"WriteLine({e});\n");
        if (family == "coll2")
            sb.Append("static class H { public static int F(Span<int> s) => s.Length; public static int F(Span<long> s) => 2; }\n");
        else if (family == "coll-nest")
            sb.Append("static class H { public static int F(ReadOnlySpan<int> s) => s.Length; public static int F(ReadOnlySpan<long> s) => 2; }\n");
        else
        {
            if (family == "f-cSome") sb.Append("static int Pass(Option<int> o) => o.UnwrapOr(0);\n");
            sb.Append("static class H { public static int F(Span<int> s) => s.Length; public static int F(ReadOnlySpan<bool> s) => 2; }\n");
            sb.Append("static class T { public static int G(out int v) { v = 1; return 0; } public static BoxS MkB(out int v) { v = 1; return new BoxS(); } }\n");
            sb.Append("sealed class BoxS { public int Sel(int x) => x; public int Sel(double x) => -2; }\n");
            sb.Append("static class XE { public static T2 EchoX<T2>(this BoxS b, T2 v) => v; }\n");
            sb.Append("sealed class W2 { public int V; public W2(int v) { V = v; } public W2(double v) { V = -3; } }\n");
            sb.Append("sealed class UX { public int Length => 4; public int this[int i] => i; }\n");
        }
        return sb.ToString();
    }
